-- More Love templates with floral/ornament skins (content.skin; art generated by scripts/gen-skins.py, inspired by Canva references).
create or replace function public.letter_clean(c jsonb, addons text[]) returns jsonb
language plpgsql immutable set search_path = '' as $$
declare
  prefix constant text := 'https://geroipkbzmbkigzwjdok.supabase.co/storage/v1/object/public/letter-media/';
  fonts constant text[] := array['serif','script','hand','sans','classic'];
  fxs constant text[] := array['opening','typing','hearts','confetti','petals','sparkles','gallery','closing'];
  decs constant text[] := array['tape','seal','ribbon','stars','border'];
  skins constant text[] := array['meadow','roses','sakura','bold','gold','lineart'];
  out jsonb := '{}'; th jsonb := '{}'; ph jsonb := '[]'; p jsonb; gf jsonb := '[]'; gn int := 0; k text; v text; maxp int; n int := 0; arr jsonb;
begin
  if c is null or jsonb_typeof(c) <> 'object' then raise exception 'Invalid letter content'; end if;
  if char_length(c::text) > 40000 then raise exception 'Letter is too large'; end if;
  out := jsonb_build_object(
    'from', left(btrim(coalesce(c->>'from','')), 60), 'to', left(btrim(coalesce(c->>'to','')), 60),
    'title', left(btrim(coalesce(c->>'title','')), 120), 'message', left(coalesce(c->>'message',''), 4000),
    'date', case when (c->>'date') ~ '^\d{4}-\d{2}-\d{2}$' then c->>'date' else '' end,
    'lang', case when c->>'lang' = 'en' then 'en' else 'id' end,
    'font', case when c->>'font' = any(fonts) then c->>'font' else 'serif' end,
    'skin', case when c->>'skin' = any(skins) then c->>'skin' else '' end);
  foreach k in array array['primary','accent','bg','paper'] loop
    v := c->'theme'->>k; if v ~ '^#[0-9a-fA-F]{6}$' then th := th || jsonb_build_object(k, lower(v)); end if;
  end loop;
  out := out || jsonb_build_object('theme', th);
  foreach k in array array['effects','decor'] loop
    arr := '[]'; if jsonb_typeof(c->k) = 'array' then
      for v in select distinct x from jsonb_array_elements_text(c->k) x loop
        if (k = 'effects' and v = any(fxs)) or (k = 'decor' and v = any(decs)) then arr := arr || to_jsonb(v); end if;
      end loop; end if;
    out := out || jsonb_build_object(k, arr);
  end loop;
  maxp := case when 'gallery' = any(addons) then 12 else 3 end;
  if jsonb_typeof(c->'photos') = 'array' then
    for p in select * from jsonb_array_elements(c->'photos') loop
      exit when n >= maxp; v := p->>'url';
      if v is not null and left(v, char_length(prefix)) = prefix and char_length(v) <= 300 and v !~ '[\s"''<>]' then
        ph := ph || jsonb_build_object('url', v, 'caption', left(btrim(coalesce(p->>'caption','')), 80)); n := n + 1; end if;
    end loop; end if;
  out := out || jsonb_build_object('photos', ph);
  if jsonb_typeof(c->'gifs') = 'array' then
    for p in select * from jsonb_array_elements(c->'gifs') loop
      exit when gn >= case when 'gallery' = any(addons) then 6 else 3 end; v := p->>'url';
      if v is not null and left(v, char_length(prefix)) = prefix and char_length(v) <= 300 and v !~ '[\s"''<>]' and v ~* '\.(gif|webp|png)$' then
        gf := gf || jsonb_build_object('url', v, 'place', case when p->>'place' in ('intro','letter','both') then p->>'place' else 'both' end); gn := gn + 1; end if;
    end loop; end if;
  out := out || jsonb_build_object('gifs', gf);
  v := c->'music'->>'url';
  if 'music' = any(addons) and v is not null and left(v, char_length(prefix)) = prefix and char_length(v) <= 300 and v !~ '[\s"''<>]' then
    out := out || jsonb_build_object('music', jsonb_build_object('url', v, 'title', left(btrim(coalesce(c->'music'->>'title','')), 60))); end if;
  return out;
end $$;


insert into public.letter_templates (slug,category_slug,name,tagline,engine,tier,price_idr,tags,defaults,options,sort_order,is_featured) values
('wildflower-letter','love','Wildflower Letter','Watercolor lavender and daisies frame a soft cream envelope.','envelope','free',0,'{romantic,cute,floral}'::text[],'{"title": "Seikat Bunga untukmu", "message": "Untukmu,\n\nAku menulis ini seperti memetik bunga liar di tepi jalan: tanpa rencana, tapi penuh rasa. Setiap kali memikirkanmu, hariku terasa lebih wangi dan lebih lembut.\n\nTerima kasih sudah menjadi tempat paling tenang untuk pulang.", "from": "", "to": "", "lang": "id", "font": "script", "theme": {"primary": "#7a5aa6", "accent": "#e9b8a6", "bg": "#f6efe0", "paper": "#fffaf0"}, "effects": ["opening", "typing", "petals", "gallery", "closing"], "decor": ["border"], "skin": "meadow"}'::jsonb,'{"effects": ["opening", "typing", "petals", "gallery", "closing"], "decor": ["border"]}'::jsonb,20,false),
('vintage-roses','love','Vintage Roses','Deep red roses and gold filigree on a velvet burgundy envelope.','envelope','premium',15000,'{romantic,elegant,luxury}'::text[],'{"title": "Selamanya Milikmu", "message": "Kekasihku,\n\nAda cinta yang datang seperti mawar: tidak tergesa, tetapi mekar dengan pasti. Begitulah aku mencintaimu, pelan, dalam, dan tidak pernah layu.\n\nSelama napas ini masih ada, namamu akan selalu kusebut dalam doa.", "from": "", "to": "", "lang": "id", "font": "classic", "theme": {"primary": "#8c1c33", "accent": "#e2bb62", "bg": "#3a0a14", "paper": "#fbefe3"}, "effects": ["opening", "typing", "petals", "hearts", "gallery", "closing"], "decor": ["seal", "border"], "skin": "roses"}'::jsonb,'{"effects": ["opening", "typing", "petals", "hearts", "gallery", "closing"], "decor": ["seal", "border"]}'::jsonb,25,true),
('sakura-dream','love','Sakura Dream','Falling cherry blossoms and a slow, dreamy confession.','cinematic','premium',15000,'{romantic,dreamy,floral}'::text[],'{"title": "Seperti Sakura", "message": "Untuk seseorang yang spesial,\n\nCintamu seperti sakura: singkat dalam waktu, tapi meninggalkan keindahan yang tak pernah bisa kulupakan.\n\nSetiap musim, aku ingin berjalan di bawah kelopak yang sama, denganmu.", "from": "", "to": "", "lang": "id", "font": "serif", "theme": {"primary": "#d9718d", "accent": "#f3a0b8", "bg": "#fde6ea", "paper": "#fff7f8"}, "effects": ["opening", "typing", "petals", "sparkles", "gallery", "closing"], "decor": [], "skin": "sakura"}'::jsonb,'{"effects": ["opening", "typing", "petals", "sparkles", "gallery", "closing"], "decor": []}'::jsonb,30,true),
('peony-box','love','Peony Box','A bold floral gift box that opens to a heartfelt card.','giftbox','free',0,'{romantic,playful,floral}'::text[],'{"title": "Kado Kecil untuk Hatimu", "message": "Hei kamu,\n\nIni kado kecil dari hatiku: sebuket bunga yang tidak akan layu, karena isinya hanya kata-kata tulus.\n\nAku sayang kamu, hari ini, besok, dan seterusnya.", "from": "", "to": "", "lang": "id", "font": "serif", "theme": {"primary": "#d9718d", "accent": "#f6d365", "bg": "#fdeaee", "paper": "#fffaf5"}, "effects": ["opening", "typing", "confetti", "petals", "gallery", "closing"], "decor": ["ribbon"], "skin": "bold"}'::jsonb,'{"effects": ["opening", "typing", "confetti", "petals", "gallery", "closing"], "decor": ["ribbon"]}'::jsonb,40,false),
('golden-night','love','Golden Night','Black and gold. A luxurious line-by-line declaration.','cinematic','premium',15000,'{romantic,dark,luxury}'::text[],'{"title": "Untukmu, Malam Ini", "message": "Sayangku,\n\nJika bintang bisa kuberi nama, semuanya akan memakai namamu.\n\nMalam ini aku hanya ingin kamu tahu: kamu adalah hal paling berharga yang pernah kumiliki.", "from": "", "to": "", "lang": "id", "font": "classic", "theme": {"primary": "#c9a24a", "accent": "#f3d98a", "bg": "#0b0907", "paper": "#f7f0e0"}, "effects": ["opening", "typing", "sparkles", "gallery", "closing"], "decor": ["stars"], "skin": "gold"}'::jsonb,'{"effects": ["opening", "typing", "sparkles", "gallery", "closing"], "decor": ["stars"]}'::jsonb,50,false),
('botanical-lines','love','Botanical Lines','Minimal line-art leaves on a clean scrapbook page.','scrapbook','free',0,'{minimal,romantic,floral}'::text[],'{"title": "Catatan Kecil untukmu", "message": "Untukmu,\n\nTidak perlu kata-kata yang rumit. Aku hanya ingin bilang bahwa bersamamu, hal-hal sederhana terasa cukup, bahkan lebih dari cukup.\n\nTerima kasih sudah tumbuh bersamaku.", "from": "", "to": "", "lang": "id", "font": "serif", "theme": {"primary": "#3f5a47", "accent": "#cbd8c3", "bg": "#f3f0e8", "paper": "#fffdf8"}, "effects": ["opening", "typing", "gallery", "closing"], "decor": ["tape"], "skin": "lineart"}'::jsonb,'{"effects": ["opening", "typing", "gallery", "closing"], "decor": ["tape"]}'::jsonb,60,false)
on conflict (slug) do nothing;
